        }
        let first = census(&parsed[0], &authored, &parsed);
        let second = census(&parsed[0], &authored, &parsed);
        assert_eq!(first.len(), second.len());
        for (a, b) in first.iter().zip(&second) {
            assert_eq!(a.0, b.0);
