        crate::parse(provider, "provider.spx").unwrap(),
    ]
}
fn padded(provider: &str) -> String {
    let mut source = provider.to_owned();
    for n in 0..256 {
        use std::fmt::Write;
        writeln!(
            source,
            "@id(\"unused.{n}\") record Unused{n} {{@id(\"unused.{n}.n\") n:i64,}}"
        )
        .unwrap();
    }
    source
}
fn fixtures() -> Vec<(&'static str, Vec<Program>)> {
