#[derive(Clone, Copy, Debug)]
struct Observation {
    ok: bool,
    capacity: usize,
    work_left: usize,
    reserved: usize,
    overflowed: bool,
    metrics: Metrics,
}
#[allow(clippy::too_many_arguments)]
fn observe<'a>(
    programs: &'a [Program],
    authored: &'a BTreeMap<&'a str, AuthoredDeclaration<'a>>,
    old: bool,
    bytes: usize,
    work: usize,
    expected: Option<&Result<LayoutClosure<'a>, Vec<Diagnostic>>>,
) -> Observation {
    let ((result, metrics), overflowed, reserved, _) = with_limit_usage_refusal(bytes, || {
        measure(|| {
            let mut remaining = work;
            let answer = if old {
                LayoutClosure::derive_with_work_before_capacity(
                    &programs[0],
                    authored,
                    programs,
                    &mut remaining,
                    None,
                )
            } else {
                LayoutClosure::derive_with_work(
                    &programs[0],
                    authored,
                    programs,
                    &mut remaining,
                    None,
                )
            };
